bounded_host_request.command:
set -eu
parent=/home/admin1/projects/debug-ai
w="$parent/.worktrees/hypothesis-review-evidence-20261028"
fixture="$parent/.worktrees/g3-semantic/.debugai-input/unicode-search-source-slice"
[ "$(realpath "$w")" = "$w" ] && [ -z "$(git -C "$w" status --porcelain --untracked-files=all)" ] || { echo DEBUGAI_SOURCE_DIRTY_OR_UNVERIFIED; exit 3; }
[ -f "$fixture/unicode-search.test.cjs" ] && [ -f "$fixture/package.json" ] || { echo DEBUGAI_REAL_FIXTURE_MISSING; exit 3; }
git -C "$parent" fetch --no-tags origin refs/heads/fix/debugai-scout-diagnosis-handoff-20261016
[ "$(git -C "$parent" rev-parse FETCH_HEAD)" = "5f4d0825dfd2d67d5c10a35b89bcb54f9ef6d6b3" ] || { echo DEBUGAI_BRANCH_MOVED; exit 4; }
git -C "$w" checkout --detach "5f4d0825dfd2d67d5c10a35b89bcb54f9ef6d6b3" >/dev/null
image=$(docker inspect -f '{{.Image}}' debug-ai-debug-ai-1)
docker run --rm --network none --read-only --cap-drop ALL --security-opt no-new-privileges --pids-limit 64 --memory 768m --cpus 1 \
 --tmpfs /tmp:rw,nosuid,nodev,size=24m,mode=1777 \
 --mount "type=bind,source=$w/server/workflow.js,target=/app/server/workflow.js,readonly" \
 --mount "type=bind,source=$fixture,target=/fixture,readonly" \
 --entrypoint node "$image" -e '
const {initialInvestigationEvidence}=require("/app/server/control/read-only-tool-runtime.js");
const {addBoundedTestDependencyEvidence}=require("/app/server/workflow.js");
const root="/fixture";
const initial=initialInvestigationEvidence(root,{request:"Investigate the Unicode source.search excerpt defect",failure:{message:"A real source.search Unicode expanding-lowercase-prefix failure"},checks:[{status:"FAIL",executed:true,timed_out:false}]});
const expanded=addBoundedTestDependencyEvidence(root,initial);
const source=x=>x.records.filter(r=>r.kind==="initial_source").map(r=>r.value.path);
const candidates=expanded.records.filter(r=>r.kind==="initial_dependency_candidate").map(r=>r.value.path);
console.log("REAL_BASELINE_PATHS="+JSON.stringify(source(initial)));
console.log("REAL_SEEDED_CANDIDATES="+JSON.stringify(candidates));
console.log("REAL_TEST_SCRIPT="+JSON.stringify(initial.records.find(x=>x.kind==="initial_test_inventory")?.value?.checks?.find(x=>x.name==="test")?.command||null));
console.log("REAL_EVIDENCE_SCOPE="+expanded.scope.mode);
console.log("REAL_COVERAGE="+expanded.scope.coverage);
console.log("REAL_DIRECT_SOURCE_VERIFIED="+String(candidates.includes("server/control/read-only-tool-runtime-base.js")));
'
echo DEBUGAI_REAL_FIXTURE_PROBE=EXECUTED
